  if(!unique.length)throw new Error("已讀取 CAD 幾何資料，但未找到可直接提取的文字或圖塊名稱。可嘗試另存為 PDF 後執行 OCR。");
  setVisualPercent(70);return {text:unique.map(line=>line.text).join("\n"),lines:unique,entities:entities.length,format:d.file_type.toUpperCase()};
