 const evidenceBacked=categorized.filter(item=>{const evidence=String(item.evidence??"").trim().toLowerCase();return evidence!==""&&evidence!=="none"&&evidence!=="null"&&evidence!=="not applicable"&&evidence!=="無"&&evidence!=="無明確證據";}).map(item=>({type:item.category??"電氣設計疑點",title:item.title??"待覆核疑點",description:item.description??item.title??"",severity:item.severity??"info",evidence:item.evidence,page_region:item.page_region,confidence:item.confidence,impact:item.impact,recommendation:item.recommendation,needs_engineer_review:true}));
